import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]

    # best[x][l] becomes the minimum right endpoint among constraints
    # targeting x whose left endpoint is at least l.
    best = [[n + 1] * (n + 2) for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        if r < best[x][l]:
            best[x][l] = r
    for x in range(1, n + 1):
        for l in range(n - 1, 0, -1):
            if best[x][l + 1] < best[x][l]:
                best[x][l] = best[x][l + 1]

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(a, b):
        return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

    # dp[l][r]: valid relative rankings for positions in [l, r].
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                # A constraint contained in [l,r] and targeting k would
                # fail if k were the maximum of this segment.
                if best[k][l] <= r:
                    continue
                left = dp[l][k - 1] if k > l else 1
                right = dp[k + 1][r] if k < r else 1
                total += choose(length - 1, k - l) * left * right
            dp[l][r] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    main()

