import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    factors = []
    primes = set()
    for x in values:
        cur = x
        fac = {}
        d = 2
        while d * d <= cur:
            if cur % d == 0:
                cnt = 0
                while cur % d == 0:
                    cur //= d
                    cnt += 1
                fac[d] = cnt
                primes.add(d)
            d += 1
        if cur > 1:
            fac[cur] = fac.get(cur, 0) + 1
            primes.add(cur)
        factors.append(fac)

    answer = 1
    for p in primes:
        steps = [fac.get(p, 0) for fac in factors]
        max_step_sum = sum(steps)
        powers = [1] * (n * max_step_sum + 1)
        for k in range(1, len(powers)):
            powers[k] = powers[k - 1] * p % MOD

        # dp[h] is the weighted sum of normalized paths whose last height is h.
        dp = [1]
        for i, a in enumerate(steps, start=1):
            nd = [0] * (len(dp) + a)
            for h, value in enumerate(dp):
                if value == 0:
                    continue
                up = h + a
                nd[up] = (nd[up] + value * powers[up]) % MOD
                if a:
                    if h >= a:
                        low = h - a
                        nd[low] = (nd[low] + value * powers[low]) % MOD
                    else:
                        # The new vertex is a lower minimum; shift all i old heights.
                        nd[0] = (nd[0] + value * powers[i * (a - h)]) % MOD
            dp = nd
        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

