import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    limit = max(a)

    # Euler's totient values.
    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for multiple in range(p, limit + 1, p):
                phi[multiple] -= phi[multiple] // p

    # Smallest prime factors, for enumerating divisors of each input value.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    # sums[d] = sum of 2^(i-1) over previous positions i with d | A_i.
    sums = [0] * (limit + 1)
    answer = 0
    weight = 1
    output = []

    for x in a:
        factors = []
        t = x
        while t > 1:
            p = spf[t]
            exponent = 0
            while t % p == 0:
                t //= p
                exponent += 1
            factors.append((p, exponent))

        divisors = [1]
        for p, exponent in factors:
            previous = divisors[:]
            power = 1
            for _ in range(exponent):
                power *= p
                divisors.extend(d * power for d in previous)

        pair_sum = sum(phi[d] * sums[d] for d in divisors) % MOD
        answer = (2 * answer + pair_sum) % MOD
        output.append(str(answer))

        for d in divisors:
            sums[d] = (sums[d] + weight) % MOD
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

