import sys

def main():
    N, M, K = map(int, sys.stdin.buffer.readline().split())
    A = list(map(int, sys.stdin.buffer.readline().split()))
    MOD = 998244353
    Q = 1 << 20

    # Walsh transform of the multiplicities of the input values gives,
    # for every character s, the number c of input elements with negative sign.
    freq = [0] * Q
    for x in A:
        freq[x] += 1
    h = freq
    step = 1
    while step < Q:
        for base in range(0, Q, step << 1):
            end = base + step
            for j in range(base, end):
                u, v = h[j], h[j + step]
                h[j], h[j + step] = u + v, u - v
        step <<= 1

    # Walsh transform of x^K.
    f = [pow(x, K, MOD) for x in range(Q)]
    step = 1
    while step < Q:
        for base in range(0, Q, step << 1):
            end = base + step
            for j in range(base, end):
                u, v = f[j], f[j + step]
                f[j], f[j + step] = (u + v) % MOD, (u - v) % MOD
        step <<= 1

    # For a character with c negative factors, the signed generating function
    # is (1-z)^c (1+z)^(N-c). Compute its coefficients cyclically mod z^M-1.
    # This implementation computes each needed polynomial by binary exponentiation.
    # Cache repeated c values.
    cache = {}
    def mul(a, b):
        out = [0] * M
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    if y:
                        out[(i + j) % M] = (out[(i + j) % M] + x * y) % MOD
        return out
    def power_linear(sign, exponent):
        # (1 + sign*z)^exponent in the cyclic ring
        result = [1] + [0] * (M - 1)
        base = [1] + [0] * (M - 1)
        base[1 % M] = sign % MOD
        e = exponent
        while e:
            if e & 1:
                result = mul(result, base)
            e >>= 1
            if e:
                base = mul(base, base)
        return result
    invQ = pow(Q, MOD - 2, MOD)
    ans = 0
    for s in range(Q):
        c = (N - h[s]) // 2
        val = cache.get(c)
        if val is None:
            a = power_linear(-1, c)
            b = power_linear(1, N - c)
            poly = mul(a, b)
            # Exclude the empty subset, which has score zero in any case;
            # its xor is zero so contributes nothing even if included.
            val = sum(poly[::M]) % MOD
            cache[c] = val
        ans = (ans + f[s] * val) % MOD
    print(ans * invQ % MOD)

