class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ends=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y))
            ends[b].append((a,i))
        hp=[]
        gains=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for a,i in ends[r]: heapq.heappush(hp,(-a,i))
            if not hp:
                total += r
                continue
            first=heapq.heappop(hp)
            top=-first[0]
            second=-hp[0][0] if hp else 0
            total += r-top
            gains[first[1]] += top-second
            heapq.heappush(hp,first)
        return total+max(gains)

