import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = []
    for _ in range(m):
        a, b, c = next(it) - 1, next(it) - 1, next(it)
        edges.append((a, b, c))

    queries = []
    ever_closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            ever_closed[e] = True
        else:
            x, y = next(it) - 1, next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if not ever_closed[e]:
            dist[a][b] = dist[b][a] = w

    # APSP in the graph after all deletions.
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            di = dist[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    answers = []
    # Undo deletions; edge insertion updates all-pairs distances in O(N^2).
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            answers.append(-1 if dist[x][y] == inf else dist[x][y])
        else:
            _, e = query
            u, v, w = edges[e]
            to_u = [dist[i][u] for i in range(n)]
            to_v = [dist[i][v] for i in range(n)]
            from_u = dist[u][:]
            from_v = dist[v][:]
            for i in range(n):
                di = dist[i]
                for j in range(i, n):
                    best = min(di[j], to_u[i] + w + from_v[j],
                               to_v[i] + w + from_u[j])
                    di[j] = best
                    dist[j][i] = best

    print('\n'.join(map(str, reversed(answers))))

if __name__ == '__main__':
    main()

