from math import comb

MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        length = len(s)

        # A number with t set bits takes 1 + steps(t) operations to reach 1.
        good_weights = []
        for t in range(1, length + 1):
            value = t
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                good_weights.append(t)

        # Count strings smaller than s by their first position differing from s.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for weight in good_weights:
                    needed = weight - prefix_ones
                    if 0 <= needed <= remaining:
                        answer += comb(remaining, needed)
                prefix_ones += 1

        return answer % MOD

