import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [math.factorial(i) for i in range(n + 1)]

        def ways(o, e, first):
            m = o + e
            if first == 1:
                need_o = (m + 1) // 2
                need_e = m // 2
            else:
                need_e = (m + 1) // 2
                need_o = m // 2
            return fact[o] * fact[e] if (o == need_o and e == need_e) else 0

        total = ways(odds, evens, 1) + ways(odds, evens, 0)
        if k > total:
            return []
        remaining = list(range(1, n + 1))
        o, e = odds, evens
        ans = []
        prev = None
        for _ in range(n):
            for i, x in enumerate(remaining):
                p = x % 2
                if prev is not None and p == prev:
                    continue
                no, ne = o - (p == 1), e - (p == 0)
                count = ways(no, ne, 1 - p)
                if k > count:
                    k -= count
                else:
                    ans.append(x)
                    remaining.pop(i)
                    o, e, prev = no, ne, p
                    break
            else:
                return []
        return ans

