class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            c = pow(10, i, k)
            if i != n - 1 - i:
                c = (c + pow(10, n - 1 - i, k)) % k
            coeff.append(c)

        # suffix[i] is a bitmask of residues obtainable using positions i..m-1.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Only residue 0 is obtainable with no positions.
        for i in range(m - 1, -1, -1):
            mask = 0
            following = suffix[i + 1]
            for r in range(k):
                if following >> r & 1:
                    for digit in range(10):
                        mask |= 1 << ((r + digit * coeff[i]) % k)
            suffix[i] = mask

        half = []
        remainder = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                needed = (-(remainder + digit * c)) % k
                if suffix[i + 1] >> needed & 1:
                    half.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        first_half = ''.join(half)
        return first_half + first_half[:n // 2][::-1]

