from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next greater element to the right
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        # A transition p -> nxt[p] represents all elements after p
        # and before the next strictly larger value, raised to nums[p].
        levels = n.bit_length()
        jump = [nxt]
        edge_cost = [[0] * n]
        for i in range(n):
            q = nxt[i]
            if q < n:
                edge_cost[0][i] = nums[i] * (q - i - 1) - (prefix[q] - prefix[i + 1])

        for _ in range(1, levels):
            prev_jump = jump[-1]
