from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # Empty pieces impose no constraint; only the nonempty literals need
        # to occur in order, without overlapping.
        pieces = [piece for piece in p.split('*') if piece]
        if not pieces:
            return 0

        def find_occurrences(word):
            m = len(word)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = prefix[j - 1]
                if word[i] == word[j]:
                    j += 1
                prefix[i] = j

            positions = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = prefix[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    positions.append(i - m + 1)
                    j = prefix[j - 1]
            return positions

        occurrences = [find_occurrences(word) for word in pieces]
        if any(not positions for positions in occurrences):
            return -1

        best = len(s) + 1
        for start in occurrences[0]:
            end = start + len(pieces[0])
            # For a fixed start, choosing each next literal's earliest
            # non-overlapping occurrence minimizes every later endpoint.
            for k in range(1, len(pieces)):
                idx = bisect_left(occurrences[k], end)
                if idx == len(occurrences[k]):
                    break
                end = occurrences[k][idx] + len(pieces[k])
            else:
                best = min(best, end - start)

        return -1 if best == len(s) + 1 else best

