import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        component = [start]
        stack = [start]
        consistent = True
        while stack:
            u = stack.pop()
            for v, z in graph[u]:
                expected = potential[u] ^ z
                if potential[v] == -1:
                    potential[v] = expected
                    component.append(v)
                    stack.append(v)
                elif potential[v] != expected:
                    consistent = False
        if not consistent:
            print(-1)
            return

        # Choose each bit of the component's common XOR offset independently.
        size = len(component)
        for bit in range(30):
            ones = sum((potential[u] >> bit) & 1 for u in component)
            if ones > size - ones:
                mask = 1 << bit
                for u in component:
                    answer[u] |= mask
        for u in component:
            answer[u] ^= potential[u]

    print(*answer)

if __name__ == '__main__':
    main()

