class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Iterative postorder traversal avoids recursion-depth limits.
        nodes = []
        left = [0] * n
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if not done:
                left[x] = len(nodes)
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))
            else:
                nodes.append(x)

        text = [s[x] for x in nodes]
        sizes = [1] * n
        # Postorder guarantees each child's size is ready before its parent.
        for x in nodes:
            if parent[x] != -1:
                sizes[parent[x]] += sizes[x]

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        answer = []
        for x in range(n):
            length = sizes[x]
            if length & 1:
                answer.append(odd[left[x] + length // 2] >= length // 2 + 1)
            else:
                answer.append(even[left[x] + length // 2] >= length // 2)
        return answer

