class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        # If x is the outlier and y is the sum element, then
        # total = x + y + y, so y = (total - x) / 2.
        for x in sorted(nums, reverse=True):
            remainder = total - x
            if remainder % 2 != 0:
                continue
            y = remainder // 2
            needed = 2 if x == y else 1
            if freq.get(y, 0) >= needed:
                return x

        # The input guarantees that a potential outlier exists.
        return 0

