    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s in dp[i] is set iff value s is obtainable at index i
        # from the processed queries covering it.
        dp = [1] * n

        if all(x == 0 for x in nums):
            return 0

        for k, (left, right, val) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << val
                # Sums larger than nums[i] cannot contribute to a solution.
                dp[i] &= (1 << (nums[i] + 1)) - 1

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

