class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10 ** len(str(n))
        low = 1 if limit == 10 else limit // 10

        # Sieve primes over the entire range of same-length values.
        prime = [True] * limit
        prime[0] = False
        if limit > 1:
            prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        # Each node's weight is its numeric value, so initialize with n
        # and add the value of every newly visited state.
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, value = heapq.heappop(pq)
            if dist[value] != cost:
                continue
            if value == m:
                return cost

            place = 1
            while place < limit:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt >= low and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(pq, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(pq, (new_cost, nxt))
                place *= 10

        return -1

