from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def zfunc(a):
            m = len(a)
            z = [0] * m
            left = right = 0
            for x in range(1, m):
                if x < right:
                    z[x] = min(right - x, z[x - left])
                while x + z[x] < m and a[z[x]] == a[x + z[x]]:
                    z[x] += 1
                if x + z[x] > right:
                    left, right = x, x + z[x]
            return z

        z0 = zfunc(nums)
        ans = 0
        for i in range(1, n - 1):
            m = n - i
            first_ok = z0[i] >= i
            if first_ok:
                start_j = max(i + 1, 2 * i)
                ans += max(0, n - start_j)

            z = zfunc(nums[i:])
            for k in range(1, m // 2 + 1):
                if z[k] >= k and (not first_ok or k < i):
                    ans += 1
        return ans

