import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    # best[p] is the maximum sum of a valid surviving-push subsequence
    # ending at an index with parity p.
    best = [None, None]
    answer = 0 if n % 2 == 0 else None

    for i, x in enumerate(a, 1):
        parity = i % 2
        current = x if parity == 1 else None  # The first survivor must be odd-indexed.

        previous = best[1 - parity]
        if previous is not None:
            extended = previous + x
            if current is None or extended > current:
                current = extended

        if current is not None and (best[parity] is None or current > best[parity]):
            best[parity] = current

        if parity == n % 2 and current is not None:
            if answer is None or current > answer:
                answer = current

    print(answer)

if __name__ == '__main__':
    main()

