from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        targets = set(targetIndices)
        m = len(pattern)
        inf = 10**9
        # dp[j] is the minimum number of target positions needed to retain
        # in order to match the first j characters of pattern.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            retain_cost = int(i in targets)
            # Descending order ensures this source position is used at most once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] < inf:
                    dp[j + 1] = min(dp[j + 1], dp[j] + retain_cost)

        # Retain the cheapest set of target positions that forms an embedding;
        # every other target position can be removed.
        return len(targetIndices) - dp[m]

