class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state gives the colors of one mirrored pair: (left, right).
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Across consecutive pairs, both left-side and right-side colors
        # must differ to satisfy adjacency.
        for i in range(1, n // 2):
            ndp = [10**30] * len(states)
            for k, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for p, (x, y) in enumerate(states):
                    if a != x and b != y:
                        ndp[k] = min(ndp[k], dp[p] + pair_cost)
            dp = ndp

        return min(dp)

